import java.util.*;

public class Main {
    static class Ledger {
        private final Map<String, Integer> balances = new HashMap<>(Map.of("A", 100, "B", 0));

        void transfer(String from, String to, int amount, boolean failAfterDebit) {
            int fromBefore = balances.get(from);
            int toBefore = balances.get(to);
            try {
                if (fromBefore < amount) throw new IllegalStateException("insufficient");
                balances.put(from, fromBefore - amount);
                if (failAfterDebit) throw new IllegalStateException("network");
                balances.put(to, toBefore + amount);
                System.out.println("committed");
            } catch (RuntimeException e) {
                balances.put(from, fromBefore);
                balances.put(to, toBefore);
                System.out.println("rolled back: " + e.getMessage());
            }
        }
    }

    public static void main(String[] args) {
        Ledger ledger = new Ledger();
        ledger.transfer("A", "B", 30, false);
        ledger.transfer("A", "B", 20, true);
        System.out.println(ledger.balances);
    }
}

